const inputData = $input.first().json;
const body = inputData.body || inputData || {};
const message = body.message || {};
const toolCall = message.toolCalls?.[0] || {};
const args = toolCall.function?.arguments || body || {};

const rawPhone = args.phone_number || args.phone || message.customer?.number || "";

// Extract digits only
let digits = rawPhone.replace(/\D/g, '');

// Standardize +639XXXXXXXXX or 9XXXXXXXXX to 09XXXXXXXXX
if (digits.startsWith('639') && digits.length === 12) {
  digits = '0' + digits.substring(2);
} else if (digits.startsWith('9') && digits.length === 10) {
  digits = '0' + digits;
}

const customerId = args.customer_id || "";

return [{
  json: {
    toolCallId: toolCall.id || "",
    customerId: customerId.trim(),
    phoneNumber: digits.trim()
  }
}];

const incoming = $('Parse Incoming Request').first().json;
const customerRow = $('Get customer by phone').first().json;
const rows = $input.all().map(item => item.json);

// Check if customer exists in tblCustomers
if (!customerRow || !customerRow['Customer ID']) {
  return [{
    json: {
      toolCallId: incoming.toolCallId,
      speechResponse: "I couldn't find any account registered under this phone number in our records.",
      count: 0
    }
  }];
}

// Filter ONLY CONFIRMED appointments
const confirmedAppointments = rows.filter(row => {
  const status = (row['Status'] || '').toUpperCase();
  return status === 'CONFIRMED' && row['Appointment ID'];
});

let speechText = "";
const customerName = customerRow['Full Name'] || 'there';

if (confirmedAppointments.length === 0) {
  speechText = `Hello ${customerName}, I checked our records, but you don't have any confirmed appointments right now.`;
} else if (confirmedAppointments.length === 1) {
  const appt = confirmedAppointments[0];
  const date = appt['Date'] || 'your scheduled date';
  const time = appt['Start'] || appt['Time'] || '';
  const purpose = appt['Purpose'] || 'your appointment';

  speechText = `Hi ${customerName}, you have a confirmed ${purpose} appointment scheduled for ${date} ${time ? 'at ' + time : ''}.`;
} else {
  const apptSummaries = confirmedAppointments.map((appt, i) => 
    `Appointment ${i + 1}: ${appt['Purpose'] || 'Service'} on ${appt['Date']}`
  ).join(". ");

  speechText = `Hi ${customerName}, you have ${confirmedAppointments.length} confirmed appointments. Here are the details: ${apptSummaries}.`;
}

return [{
  json: {
    toolCallId: incoming.toolCallId,
    speechResponse: speechText,
    count: confirmedAppointments.length
  }
}];
